import React, { ElementType, forwardRef, ReactElement, useMemo } from 'react';
import { isElement } from 'react-is';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';
import { getAppName } from '@dynatrace-sdk/app-environment';

import { ActionGroup } from './action-group/ActionGroup.js';
import { AppIcon } from './AppIcon.js';
import { useActionItemsContext } from './hooks/useActionItemsContext.js';
import { useNavItemsContext } from './hooks/useNavItemsContext.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { PolymorphicComponentProps } from '../../core/types/polymorph.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { Text } from '../../typography/Text.js';

// #region Typings
export interface AppNavLinkInternalOwnProps
  extends AriaLabelingProps,
    WithChildren,
    StylingProps,
    DataTestId {
  /** The route where the NavItem navigates to. */
  href?: string;
  /** The name of the app. */
  appName?: string;
  /** If set to true, the item will not be moved into the menu in case of insufficient space. */
  pin?: boolean;
}

export type AppNavLinkInternalProps<E extends ElementType> =
  PolymorphicComponentProps<E, AppNavLinkInternalOwnProps>;

type SlotsType = {
  icon?: ReactElement;
};
// #endregion

// #region Styled Components
const StyledAppName: typeof Text = styled(Text)({
  width: '100%',
  whiteSpace: 'nowrap',
  overflow: 'hidden',
  textOverflow: 'ellipsis',
});
// #endregion

/**
 * A navigation link which can be used to go to the home page.
 */
export const AppNavLinkInternal: <E extends ElementType = 'a'>(
  props: AppNavLinkInternalProps<E>,
) => ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends ElementType>(
    props: AppNavLinkInternalProps<E>,
    forwardedRef: typeof props.ref,
  ) => {
    const defaultAppName = useMemo(() => getAppName?.() || '', []); // using the <AppName/> component would generate an extra <div> that wraps the text for styling, which would break the ellipsis overflow
    const defaultAppIcon = useMemo(
      // A11y: alt text must not duplicate existing text.
      () => <AppIcon alt={`${defaultAppName} icon`} />,
      [defaultAppName],
    ); // we need to memoize the icon so we don't recreate it every time the nav collapsed state changes
    const {
      appName = defaultAppName,
      href = '/',
      as: propAs,
      children,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: AppNavLinkInternalProps<E> = props;
    const as = propAs ?? 'a';

    const slots = useMemo(() => {
      const slots: SlotsType = {};

      for (const child of React.Children.toArray(children)) {
        if (isElement(child) && child.type === AppIcon) {
          slots.icon = React.cloneElement(child, {
            ..._mergeProps(child.props, {
              // A11y: alt text must not duplicate existing text.
              alt: child.props.alt ?? `${appName} icon`,
            }),
          });
        }
      }

      return slots;
    }, [appName, children]);

    const { hasNavItems, isNavOverflowing } = useNavItemsContext();
    const { hasActions, isActionItemsCollapsed } = useActionItemsContext();

    const appNameMaxWidth = isNavOverflowing // this is false if there is no nav item added
      ? `calc(100% - ${Spacings.Size16} - ${Spacings.Size36})` // this accounts for the button padding, space between the dot icon trigger and the app name, flex gap, burger menu trigger and the dot icon trigger (doesn't account for the appshell dock width)
      : `calc(100% - ${Spacings.Size20})`; // no nav item => nothing to collapse => no burger menu icon on the left, so we should only subtract the button padding (16px) and the flex gap (4px)
    const maxWidth =
      isActionItemsCollapsed && hasNavItems ? appNameMaxWidth : '100%';
    const iconHiddenWhenOverflowing = !isNavOverflowing
      ? slots.icon
      : undefined; // hide the icon if the nav items are collapsed (to show the burger menu icon instead)
    const iconWithFallback =
      !hasNavItems && !hasActions ? defaultAppIcon : iconHiddenWhenOverflowing; // show the default icon when <AppHeader /> is used

    return (
      <ActionGroup.ActionButton<ElementType>
        ref={forwardedRef}
        data-testid={dataTestId}
        type="button"
        href={href}
        as={as}
        prefixIcon={iconWithFallback}
        showLabel
        {...remainingProps}
        className={consumerClassName}
        style={{
          paddingRight: Spacings.Size12,
          gap: 8,
          maxWidth,
          ...consumerStyle,
        }}
      >
        <StyledAppName textStyle="base-emphasized">{appName}</StyledAppName>
      </ActionGroup.ActionButton>
    );
  },
);

(
  AppNavLinkInternal as typeof AppNavLinkInternal & { displayName: string }
).displayName = 'AppHeader.AppNavLink';
